#include "resident/checkpoint/checkpoint_economic_index_copy.hpp"
// 同代有限来源索引与当前公职重验；只读真实税债、付款和原受益公库细余数。
#include "occupation_fiscal_view.hpp"
#include "../takeover/responsibility_execution.hpp"
#include "resident/domains/organization/organization_model.hpp"
namespace hanmo::resident {
namespace {
// 源索引和游标必须绑定完整世界身份，不能跨冷恢复或换人续读。
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
// 公职身份键保留任期与本人，不能只凭组织名复用旧源。
LocalEconomyAuthorityKey authority_key(const ActingAuthority& a){return {a.organization_id,a.office_id,a.authority_epoch,a.actor_id};}
// 机构税务需要该地点与对应公账的明确读grant；组织纳税者只能读取自己原付款账户的责任。
bool may_read(const OrganizationRead& organizations,const FiscalSourceAssessment& assessment,const FiscalPolicySnapshot& policy,const ActingAuthority& authority){
    if(!organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,policy.site_id},0).ok)return false;
    StableId account;if(authority.organization_id==policy.organization_id)account=policy.public_wallet_id;else if(assessment.owner.kind==Owner::Kind::organization&&assessment.owner.id==authority.organization_id)account=assessment.wallet_id;else return false;
    return organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::account,account},0).ok;
}
}
Outcome<FiscalSettlementIndex> build_occupation_fiscal_settlement_index(const OccupationFiscalSettlementContext& x,const OccupationFiscalSettlementState& state,const OrganizationState& organization){
    auto valid=validate_occupation_fiscal_settlement(x,state);if(!valid.ok)return {false,{},valid.error};if(x.phase)return {false,{},common_failure("OccupationFiscalPageRequiresCommittedClock").error};const auto& common=x.common;const auto& organizations=x.organizations;
    FiscalSettlementIndex index;index.identity=common.state().identity;index.observer_actor_id=index_memory::copy(index.text_memory,common.state().metadata.player_actor_id);const auto* actor=common.actor(index.observer_actor_id);auto location=common.resolved_location(index.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here)return {true,std::move(index),{}};index.place_id=index_memory::copy(index.text_memory,here->place_id);
    for(const auto& row:organization.offices.rows()){const auto& office=row.second;if((!office.holder_actor_id||*office.holder_actor_id!=actor->id)&&(!office.deputy_actor_id||*office.deputy_actor_id!=actor->id))continue;CheckpointMemoryCharge authority_memory;auto authority=index_memory::authority(authority_memory,office.organization_id,office.id,office.epoch,actor->id);if(!organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,here->place_id},0).ok)continue;index.authorities.push_back(index_memory::copy(index.text_memory,authority));index_memory::authority_entry(index.text_memory,index.sources,authority);}
    for(const auto& row:state.assessments.rows()){const auto* period=state.periods.find(row.second.assessment.period_id);if(!period||period->policy.site_id!=here->place_id||period->due_tick>common.tick())continue;for(const auto& authority:index.authorities)if(may_read(organizations,row.second.assessment,period->policy,authority))index_memory::authority_entry(index.text_memory,index.sources,authority).push_back(index_memory::copy(index.text_memory,row.first));}
    for(const auto& row:state.suspended_periods.rows()){const auto& p=row.second.period;if(p.policy.site_id!=here->place_id||p.due_tick>common.tick())continue;for(const auto& authority:index.authorities)if(authority.organization_id==p.policy.organization_id&&organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::account,p.policy.public_wallet_id},0).ok)index_memory::authority_entry(index.text_memory,index.sources,authority).push_back(index_memory::copy(index.text_memory,row.first));}
    return {true,std::move(index),{}};
}
// query只遍历合法ID序列；无权限者返回合法空页，未知/远方记录不改变offset与scanned。
Outcome<OccupationFiscalSettlementPage> query_occupation_fiscal_settlement(const OccupationFiscalSettlementContext& x,const OccupationFiscalSettlementState& state,const FiscalSettlementIndex& index,const LocalEconomyQuery& query){
    const auto& common=x.common;const auto& organizations=x.organizations;const auto& catalog=x.catalog;if(x.phase)return {false,{},common_failure("OccupationFiscalPageRequiresCommittedClock").error};
    const auto fail=[](const StableId& code)->Outcome<OccupationFiscalSettlementPage>{return {false,{},common_failure(code).error};};
    if(catalog.version!=1||catalog.districts.empty()||state.version!=1)return fail("FiscalSettlementUnavailable");if(query.observer_actor_id.empty()||query.observer_actor_id!=common.state().metadata.player_actor_id)return fail("LocalEconomyObserverRequired");const auto* actor=common.actor(query.observer_actor_id);auto location=common.resolved_location(query.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here||here->place_id!=query.place_id)return fail("LocalEconomyPlaceNotObservable");if(state.last_step_tick!=common.tick())return fail("FiscalSettlementClockMismatch");if(!same_identity(index.identity,common.state().identity)||index.observer_actor_id!=query.observer_actor_id||index.place_id!=query.place_id)return fail("StaleFiscalSettlementIndex");
    const CheckpointVector<StableId> empty;const auto* sources=&empty;
    if(query.authority){const auto& a=*query.authority;if(a.actor_id!=query.observer_actor_id)return fail("LocalEconomyAuthorityActorMismatch");auto allowed=organizations.authorize(a,"inspect_local_economy",{ScopeRef::Kind::site,query.place_id},0);if(!allowed.ok)return {false,{},allowed.error};auto found=index.sources.find(authority_key(a));if(found==index.sources.end())return fail("StaleFiscalSettlementIndex");sources=&found->second;}
    Integer offset=0;if(query.cursor){const auto& c=*query.cursor;if(!same_identity(c.identity,common.state().identity)||c.observer_actor_id!=query.observer_actor_id||c.place_id!=query.place_id||c.authority.has_value()!=query.authority.has_value()||(c.authority&&authority_key(*c.authority)!=authority_key(*query.authority)))return fail("StaleLocalEconomyCursor");offset=c.offset;}if(sources->size()>static_cast<std::size_t>(INT64_MAX)||offset<0||offset>static_cast<Integer>(sources->size()))return fail("InvalidLocalEconomyCursor");
    OccupationFiscalSettlementPage result;auto& page=result.base;page.identity=common.state().identity;page.observer_actor_id=query.observer_actor_id;page.place_id=query.place_id;page.cursor=offset;page.authorities.assign(index.authorities.begin(),index.authorities.end());
    while(offset<static_cast<Integer>(sources->size())&&(page.rows.size()+result.suspensions.size())<static_cast<std::size_t>(local_economy_page_limit)){
        const auto selected_id=(*sources)[static_cast<std::size_t>(offset++)];++page.scanned;if(const auto* paused=state.suspended_periods.find(selected_id)){const auto& p=paused->period;if(!query.authority||query.authority->organization_id!=p.policy.organization_id||p.policy.site_id!=query.place_id||p.due_tick>common.tick()||!organizations.authorize(*query.authority,"inspect_local_economy",{ScopeRef::Kind::account,p.policy.public_wallet_id},0).ok)return fail("StaleFiscalSettlementIndex");OccupationFiscalSuspensionRow row{p.id,p.district_id,p.policy.site_id,p.policy.organization_id,p.policy.source_fact_id,p.policy.public_wallet_id,p.policy.public_inventory_id,p.due_tick,{}};for(const auto& source:paused->sources)row.source_ids.push_back(source.source_id);result.suspensions.push_back(std::move(row));continue;}const auto* record=state.assessments.find(selected_id);const auto* assessment=record?&record->assessment:nullptr;const auto* period=assessment?state.periods.find(assessment->period_id):nullptr;if(!assessment||!period||!query.authority||period->policy.site_id!=query.place_id||period->due_tick>common.tick()||!may_read(organizations,*assessment,period->policy,*query.authority))return fail("StaleFiscalSettlementIndex");const auto& policy=period->policy;
        page.rows.push_back({assessment->id,period->id,assessment->source_id,policy.site_id,policy.jurisdiction_id,policy.organization_id,assessment->grain_item_id,policy.source_fact_id,period->due_tick,assessment->cash.original_due,assessment->cash.paid_amount,assessment->cash.original_due-assessment->cash.paid_amount,assessment->grain.original_due,assessment->grain.paid_amount,assessment->grain.original_due-assessment->grain.paid_amount,assessment->produced_grain,assessment->civilian_grain_reserve,policy.mode});
        OccupationFiscalAssessmentDetail detail;detail.assessment_id=assessment->id;detail.public_wallet_id=policy.public_wallet_id;detail.public_inventory_id=policy.public_inventory_id;detail.occupation_fact_id=period->occupation_fact_id;detail.registration_fact_id=period->registration_fact_id;detail.income_basis_points=period->income_basis_points;
        for(const auto& bucket:state.buckets)if(bucket.key.district_id==period->district_id&&bucket.key.source_id==assessment->source_id&&bucket.key.organization_id==policy.organization_id){if(bucket.key.kind==FiscalIncomeAccountKind::cash&&bucket.key.public_account_id==policy.public_wallet_id)detail.cash_bucket=bucket.remainder;if(bucket.key.kind==FiscalIncomeAccountKind::grain&&bucket.key.public_account_id==policy.public_inventory_id)detail.grain_bucket=bucket.remainder;}
        auto historical=x.policies.occupation_fiscal_policy_for_assessment_source(policy.site_id,period->due_tick,policy.source_fact_id);if(!historical.ok)return {false,{},historical.error};if(!historical.value)return fail("MissingOccupationFiscalPolicySource");if(historical.value->control_loss&&common.tick()>=historical.value->control_loss->occupation_tick)detail.collection_pause_reason="original_beneficiary_control_lost";if(assessment->owner.kind==Owner::Kind::organization){const auto* cash=common.wallet(assessment->wallet_id);const auto* grain=common.inventory(assessment->inventory_id);if(!cash||!grain)return fail("FiscalSourceAssetMismatch");if(!owner_equal(cash->owner,assessment->owner)||!owner_equal(grain->owner,assessment->owner))detail.collection_pause_reason="original_taxpayer_assets_captured";}
        if(x.takeover&&detail.collection_pause_reason.empty()){auto plan=read_economic_takeover_execution(*x.takeover,{EconomicResponsibilityKind::fiscal_assessment,assessment->id,{}});if(!plan.ok)return {false,{},plan.error};if(plan.value)detail.collection_pause_reason="responsibility_under_takeover";}
        for(const auto& payment:state.payments.rows())if(payment.second.assessment_id==assessment->id)detail.payment_fact_ids.push_back(payment.first);result.details.push_back(std::move(detail));
        auto& visible=page.rows.back();auto cash=index.need_by_arrear.find(assessment->cash.id);if(cash!=index.need_by_arrear.end())visible.cash_need=cash->second;auto grain=index.need_by_arrear.find(assessment->grain.id);if(grain!=index.need_by_arrear.end())visible.grain_need=grain->second;
    }
    if(offset<static_cast<Integer>(sources->size()))page.next_cursor=LocalEconomyCursor{page.identity,query.observer_actor_id,query.place_id,query.authority,offset};return {true,std::move(result),{}};
}
BoundaryValue encode_occupation_fiscal_settlement_page(const OccupationFiscalSettlementPage& page){using V=BoundaryValue;auto out=encode_fiscal_settlement_page(page.base);auto& rows=*out.find("rows")->as<V::Array>();if(rows.size()!=page.details.size())boundary::fail("InvalidOccupationFiscalPage","/occupation_fiscal_settlement");for(std::size_t n=0;n<rows.size();++n){const auto& detail=page.details[n];if(detail.assessment_id!=page.base.rows[n].assessment_id)boundary::fail("InvalidOccupationFiscalPage","/occupation_fiscal_settlement");auto& fields=*rows[n].as<V::Dict>();*rows[n].find("kind")=V{"occupation_tax_assessment"};fields.emplace_back("public_wallet_id",V{detail.public_wallet_id});fields.emplace_back("public_inventory_id",V{detail.public_inventory_id});fields.emplace_back("occupation_fact_id",V{detail.occupation_fact_id});fields.emplace_back("registration_fact_id",V{detail.registration_fact_id});fields.emplace_back("income_basis_points",V{detail.income_basis_points});fields.emplace_back("collection_pause_reason",V{detail.collection_pause_reason});fields.emplace_back("cash_bucket",boundary::obj({{"coarse",V{detail.cash_bucket.coarse}},{"fine",V{detail.cash_bucket.fine}}}));fields.emplace_back("grain_bucket",boundary::obj({{"coarse",V{detail.grain_bucket.coarse}},{"fine",V{detail.grain_bucket.fine}}}));V::Array payments;for(const auto& id:detail.payment_fact_ids)payments.push_back(V{id});fields.emplace_back("payment_fact_ids",V{std::move(payments)});}V::Array suspended;for(const auto& row:page.suspensions){V::Array ids;for(const auto& id:row.source_ids)ids.push_back(V{id});suspended.push_back(boundary::obj({{"kind",V{"occupation_tax_period_suspended"}},{"fact_id",V{row.fact_id}},{"district_id",V{row.district_id}},{"site_id",V{row.site_id}},{"organization_id",V{row.organization_id}},{"policy_fact_id",V{row.policy_fact_id}},{"public_wallet_id",V{row.public_wallet_id}},{"public_inventory_id",V{row.public_inventory_id}},{"due_tick",V{row.due_tick}},{"reason",V{"original_taxpayer_assets_captured"}},{"source_ids",V{std::move(ids)}}}));}out.as<V::Dict>()->emplace_back("suspended_periods",V{std::move(suspended)});return out;}
}
